head.script:
scwin.init = function() {
    var grd_str =
        '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" scrollByColumnAdaptive="false" rowStatusVisible="" fixedColumn="1" dataList="data:dlSparePartKitByOfficeSetup" style="height: 350px;width:675px;border:1px solid;" scrollByColumn="false"   ' +
        'id="gvSparePartKitByOfficeSetup" autoFit="none" defaultCellHeight="20" class="cm_grid">                                                                                                                                 ' +
        '       <w2:caption style="" id="caption1" value="this is a grid caption."/>                                                                                                                                                 ' +
