        '                       </w2:column>                                                                                                                                                                                                 ' +
        '               <w2:column xmlns:w2="http://www.inswave.com/websquare" id="CA01_header" inputType="text" value="CA01" width="120"/><w2:column xmlns:w2="http://www.inswave.com/websquare" id="CA03_header" inputType="text"      ' +
        '               value="CA03" width="120"/><w2:column xmlns:w2="http://www.inswave.com/websquare" id="DK01_header" inputType="text" value="DK01" width="120"/></w2:row>                                                           ' +
        '       </w2:header>                                                                                                                                                                                                         ' +
        '       <w2:gBody style="" id="gBody1">                                                                                                                                                                                      ' +
        '               <w2:row style="" id="bodyRow">                                                                                                                                                                                   ' +
        '                       <w2:column removeBorderStyle="false" width="100" inputType="text" style="" id="mf_wcMain_subWindow0_wframe_UIMNR8041_wframe_gvSparePartKitByOfficeSetup_ofceCd" value="" blockSelect="false"                 ' +
        '                       displayMode="label" readOnly="true" col_id="ofceCd">                                                                                                                                                         ' +
        '                       </w2:column>                                                                                                                                                                                                 ' +
