        '               textAlign="right" displayFormat="#,##0" readOnly="true"/><w2:column xmlns:w2="http://www.inswave.com/websquare" id="grandTotal21Value" dataType="number" inputType="expression"                                  ' +
        '               expression="MAX(\'ofceKitTotCostAmt1Value\') * SUM(\'kitSum1Value\') ;" value="0" textAlign="right" displayFormat="#,##0" readOnly="true"/><w2:column xmlns:w2="http://www.inswave.com/websquare"                    ' +
