        '               </w2:row>                                                                                                                                                                                                        ' +
        '       </w2:footer>                                                                                                                                                                                                         ' +
        '</w2:gridView>                                                                                                                                                                                                          ';
    gvSparePartKitByOfficeSetup.setGridStyle(WebSquare.xml.parse(grd_str, true));
