            "ofceCd": "PUSSB",
            "rfSprPartKitNo": "Set Quantity",
            "kitSum0Value": "423",
            "kitSum1Value": "11",
            "kitSum2Value": "222",
            "ofceKitTotCostAmt0Value": "4",
            "ofceKitTotCostAmt1Value": "5",
            "ofceKitTotCostAmt2Value": "1"
        },
        {
            "ofceCd": "SHAHQ",
            "rfSprPartKitNo": "Set Quantity",
            "kitSum0Value": "22",
            "kitSum1Value": "22",
            "kitSum2Value": "1111",
            "ofceKitTotCostAmt0Value": "6",
            "ofceKitTotCostAmt1Value": "7",
            "ofceKitTotCostAmt2Value": "3"
        },
        {
            "ofceCd": "SINHQ",
            "rfSprPartKitNo": "Set Quantity",
            "kitSum0Value": "22",
            "kitSum1Value": "11",
            "kitSum2Value": "9",
            "ofceKitTotCostAmt0Value": "8",
            "ofceKitTotCostAmt1Value": "9",
            "ofceKitTotCostAmt2Value": "7"
