scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gvSparePartKitByOfficeSetup__kitSum0Value', 'key-sequence', {
        sequence: '5'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gvSparePartKitByOfficeSetup__kitSum0Value', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#G_gvSparePartKitByOfficeSetup__kitSum0Value', 'key-combo', {
        combo: 'DEL'
    });
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
}
scwin.checkColor = function(id, rgb) {
    var element = WebSquare.wUnit.getDomById($p.id + id)
    var color = WebSquare.wUnit.getJq($(element).children()[0]).css("color");
    return color == rgb;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gvSparePartKitByOfficeSetup_cell_2_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gvSparePartKitByOfficeSetup_dataLayer').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gvSparePartKitByOfficeSetup_grandTotal10Value').innerText == '505'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
	scwin.init()
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
